//! Oracle rows and the replay engine for the charged brush store (L07-D / G06).
//!
//! `fixtures/bitmap-brush-resources-store/oracle.txt` was generated by
//! `tools/gen_oracle.js` from baseline fbe4b8a3: the VERBATIM
//! `src/js/application/render/image-budget.js` runs in a Node `vm` over pinned and
//! seeded operation sequences. Rows (`#` lines are provenance):
//! `Q name ops => results`, `G number budget`, `C w h bytes`. `replay` drives the
//! real store with the same operations and renders the same result text, so a
//! mutated `StoreRules` can be compared row by row.

use super::{BrushBitmapStore, StoreRules};
use crate::revision::ImageResourceBudget;

pub(crate) const ORACLE: &str = include_str!("fixtures/bitmap-brush-resources-store/oracle.txt");

/// Data rows of one kind (`Q`, `G` or `C`), without the tag.
pub(crate) fn rows(tag: char) -> Vec<&'static str> {
    rows_in(ORACLE, tag)
}

pub(crate) fn rows_in(text: &str, tag: char) -> Vec<&str> {
    text.lines()
        .filter(|line| line.starts_with(tag) && line[1..].starts_with(' '))
        .map(|line| &line[2..])
        .collect()
}

fn join(ids: &[String]) -> String {
    if ids.is_empty() {
        "-".to_string()
    } else {
        ids.join(",")
    }
}

/// Runs `ops` on a store with a roomy isolated hard quota and renders the
/// oracle's result text. Every publish handle is dropped at once: the oracle
/// holds no scene lease, so only the build set pins.
pub(crate) fn replay(rules: StoreRules, ops: &str) -> String {
    let budget = ImageResourceBudget::isolated(64 * 1024 * 1024).unwrap();
    let mut store = BrushBitmapStore::with_rules(budget, rules);
    let mut out: Vec<String> = Vec::new();
    for op in ops.split(';') {
        let parts: Vec<&str> = op.split(':').collect();
        match parts[0] {
            "S" => {
                store.set_budget_bytes(parts[1].parse::<f64>().unwrap());
            }
            "B" => store.begin_build(),
            "R" => {
                let w = parts[2].parse::<u32>().unwrap();
                let h = parts[3].parse::<u32>().unwrap();
                let pixels = vec![0u8; w as usize * h as usize * 4];
                if let Err(error) = store.publish(parts[1], w, h, &pixels, None) {
                    out.push(format!("ERR:{error:?}"));
                }
            }
            "T" => store.touch(parts[1]),
            "E" => {
                let mode = parts[1];
                let mut seen: Vec<String> = Vec::new();
                let dropped = {
                    let mut port = |ids: &[String]| {
                        seen.extend(ids.iter().cloned());
                        mode == "t"
                    };
                    if mode == "n" {
                        store.end_build(None)
                    } else {
                        store.end_build(Some(&mut port))
                    }
                };
                out.push(format!("E:{}/{}", join(&dropped), join(&seen)));
            }
            other => panic!("unknown oracle op {other}"),
        }
    }
    let stats = store.stats();
    let budget_text = if stats.budget_bytes == u64::MAX {
        "max".to_string()
    } else {
        stats.budget_bytes.to_string()
    };
    out.push(format!(
        "F:{}:{}:{}:{}:{}:{}",
        stats.total_bytes,
        budget_text,
        stats.evictions,
        stats.count,
        u8::from(store.building()),
        join(&store.ids())
    ));
    out.join(";")
}

/// The oracle prints a NaN budget as `nan`; the store has no NaN, and NaN never
/// evicts, which is exactly its unlimited budget.
pub(crate) fn normalize_budget_token(text: &str) -> &str {
    if text == "nan" {
        "max"
    } else {
        text
    }
}

/// Rows whose replay differs from the baseline text (empty when they all agree).
pub(crate) fn sequence_mismatches(rules: StoreRules) -> Vec<String> {
    sequence_mismatches_in(rules, ORACLE)
}

pub(crate) fn sequence_mismatches_in(rules: StoreRules, text: &str) -> Vec<String> {
    rows_in(text, 'Q')
        .into_iter()
        .filter_map(|row| {
            let (head, expected) = row.split_once(" => ").unwrap();
            let (name, ops) = head.split_once(' ').unwrap();
            let expected: Vec<String> = expected
                .split(';')
                .map(|part| {
                    let mut fields: Vec<&str> = part.split(':').collect();
                    if fields[0] == "F" {
                        fields[2] = normalize_budget_token(fields[2]);
                    }
                    fields.join(":")
                })
                .collect();
            let expected = expected.join(";");
            let actual = replay(rules, ops);
            (actual != expected).then(|| format!("{name}: expected {expected} got {actual}"))
        })
        .collect()
}

pub(crate) fn fresh(limit: usize) -> (BrushBitmapStore, ImageResourceBudget) {
    let budget = ImageResourceBudget::isolated(limit).unwrap();
    (BrushBitmapStore::with_budget(budget.clone()), budget)
}
pub(crate) fn pattern(w: u32, h: u32, seed: u8) -> Vec<u8> {
    (0..w as usize * h as usize * 4)
        .map(|i| (i as u8).wrapping_mul(7).wrapping_add(seed))
        .collect()
}
pub(crate) fn used(budget: &ImageResourceBudget) -> usize {
    budget.used().unwrap()
}
/// Publishing `w*h` pixels charges exactly `w*h*4` (the JS `noteRegistered` bytes).
pub(crate) fn cost_scenario(rules: StoreRules) -> Vec<String> {
    let budget = ImageResourceBudget::isolated(1 << 20).unwrap();
    let mut store = BrushBitmapStore::with_rules(budget.clone(), rules);
    match store.publish("a", 10, 10, &pattern(10, 10, 1), None) {
        Ok(handle) if handle.cost() == 400 && used(&budget) == 400 => Vec::new(),
        Ok(handle) => vec![format!("cost {} used {}", handle.cost(), used(&budget))],
        Err(error) => vec![format!("publish refused {error:?}")],
    }
}

/// A replacement keeps the old version alive and charged for its holder, and the
/// holder can tell it is stale (versions only rise).
pub(crate) fn fence_scenario(rules: StoreRules) -> Vec<String> {
    let mut failures = Vec::new();
    let budget = ImageResourceBudget::isolated(1 << 20).unwrap();
    let mut store = BrushBitmapStore::with_rules(budget.clone(), rules);
    let first = pattern(10, 10, 1);
    let old = store.publish("a", 10, 10, &first, None).unwrap();
    let new = store
        .publish("a", 10, 10, &pattern(10, 10, 2), None)
        .unwrap();
    let checks = [
        (old.rgba8() == first.as_slice(), "old pixels unchanged"),
        (!store.is_current(&old), "old handle reports stale"),
        (store.is_current(&new), "new handle is current"),
        (new.version() > old.version(), "version rose"),
        (used(&budget) == 800, "both versions charged while held"),
        (!old.same_allocation_as(&new), "distinct allocations"),
    ];
    failures.extend(checks.iter().filter(|c| !c.0).map(|c| c.1.to_string()));
    drop(old);
    if used(&budget) != 400 {
        failures.push(format!("old charge not released: {}", used(&budget)));
    }
    failures
}

/// The oldest entry is held by a scene: `end_build` must drop the newer one.
pub(crate) fn lease_scenario(rules: StoreRules) -> Vec<String> {
    let budget = ImageResourceBudget::isolated(1 << 20).unwrap();
    let mut store = BrushBitmapStore::with_rules(budget, rules);
    let held = store
        .publish("a", 10, 10, &pattern(10, 10, 1), None)
        .unwrap();
    store
        .publish("b", 10, 10, &pattern(10, 10, 2), None)
        .unwrap();
    store.set_budget_bytes(400.0);
    let mut port = |_: &[String]| true;
    let dropped = store.end_build(Some(&mut port));
    let mut failures = Vec::new();
    if dropped != ["b"] {
        failures.push(format!("dropped {dropped:?}"));
    }
    if !store.contains("a") || held.holders() != 2 {
        failures.push("leased entry lost".to_string());
    }
    failures
}

#[test]
fn oracle_provenance_and_row_counts_are_pinned() {
    assert!(ORACLE.contains("baseline fbe4b8a33e6d5a229f014154df2ba21988a9fabc"));
    assert!(ORACLE.contains(
        "image-budget.js sha256 c93eb2d0ef588abd31d7c2ca2d4d04d255351447e1c16e1ceb2465c22060966f"
    ));
    assert!(ORACLE.contains("# counts {\"Q\":321,\"G\":20,\"C\":70} total 411"));
    assert_eq!(
        (rows('Q').len(), rows('G').len(), rows('C').len()),
        (321, 20, 70)
    );
}

#[test]
fn lru_sequences_equal_the_verbatim_baseline_on_321_rows() {
    let mismatches = sequence_mismatches(StoreRules::BASELINE);
    assert!(
        mismatches.is_empty(),
        "{} rows differ, first: {:?}",
        mismatches.len(),
        mismatches.first()
    );
}

#[test]
fn budget_setter_rows_equal_the_baseline_number_handling() {
    for row in rows('G') {
        let (token, expected) = row.split_once(' ').unwrap();
        let (mut store, _) = fresh(1 << 20);
        let actual = if token.starts_with("default") {
            store.stats().budget_bytes
        } else {
            store.set_budget_bytes(token.parse::<f64>().unwrap())
        };
        let expected = match normalize_budget_token(expected) {
            "max" => u64::MAX,
            text => text.parse::<u64>().unwrap(),
        };
        assert_eq!(actual, expected, "G {token}");
    }
}

#[test]
fn cost_rows_equal_width_times_height_times_four() {
    for row in rows('C') {
        let f: Vec<u64> = row.split(' ').map(|t| t.parse().unwrap()).collect();
        assert_eq!(
            StoreRules::BASELINE.cost(f[0] as u32, f[1] as u32),
            Some(f[2] as usize),
            "C {row}"
        );
        if f[2] <= 1 << 22 {
            let (mut store, budget) = fresh(1 << 23);
            let rgba = pattern(f[0] as u32, f[1] as u32, 3);
            let handle = store
                .publish("a", f[0] as u32, f[1] as u32, &rgba, None)
                .unwrap();
            assert_eq!(
                (handle.cost() as u64, used(&budget) as u64),
                (f[2], f[2]),
                "C {row} charge"
            );
            assert_eq!(handle.rgba8(), rgba.as_slice());
        }
    }
}

#[test]
fn baseline_rules_scenarios_and_literals_hold() {
    assert!(cost_scenario(StoreRules::BASELINE).is_empty());
    assert!(fence_scenario(StoreRules::BASELINE).is_empty());
    assert!(lease_scenario(StoreRules::BASELINE).is_empty());
    let rules = StoreRules::BASELINE;
    assert_eq!(
        (
            rules.bytes_per_pixel,
            rules.budget_inclusive,
            rules.protect_current_build
        ),
        (4, true, true)
    );
    assert_eq!(
        (rules.protect_leased, rules.new_version_on_replace),
        (true, true)
    );
}
